(()=>{'use strict';const $=id=>document.getElementById(id),q=new URLSearchParams(location.search),root=document.querySelector('.studio');let story=q.get('story')||'default',principal=q.get('principal')||'',tools=[],form=null,current=null,busy=false,last=null,controller=null,execution=null,executedRequest=null;
root.dataset.embed=q.get('embed')==='true';const flow={title:'Two checks with a durable wait',nodes:[{id:'checks',type:'parallel',concurrency:2,branches:[{id:'orders',nodes:[{id:'lookup',type:'tool',tool:'find',arguments:{q:'orders'}}]},{id:'billing',nodes:[{id:'lookup',type:'tool',tool:'find',arguments:{q:'billing'}}]}]},{id:'pause',type:'wait',ms:100},{id:'again',type:'loop',iterations:2,nodes:[{id:'lookup',type:'tool',tool:'find',arguments:{q:'orders'}}]}]};
const intents=[{id:'continue',title:'Resume a task',purpose:'Choose a stable saved task and attach it to this chat. Files and progress remain owned by the same user.',names:['continuation_'],starters:[['Create task','continuation_create',{task_id:'RELEASE-CHECK',title:'Release verification',summary:'Retain release evidence and next steps across chats'}],['Find saved tasks','continuation_find',{}],['Prepare task-backed checks','continuation_flow',{action:'save',arguments:{id:'task-checks',expected_revision:null,definition:flow}}]]},{id:'repositories',title:'Upgrade dependencies',purpose:'Index every Gradle build file at exact repository SHAs, inspect version ownership, then review a guarded upgrade plan.',names:['gradle_'],starters:[['Index selected repositories','gradle_inventory',{action:'index',repos:[]}],['Browse retained indices','gradle_inventory',{action:'list'}]]},{id:'flows',title:'Coordinate work',purpose:'Save an explicit loop/parallel/wait program. Start and resume are separate actions; model calls require explicit permission.',names:['automation_flow_'],starters:[['Prepare parallel + loop example','automation_flow_save',{id:'release-checks',expected_revision:null,definition:flow}],['Find saved programs','automation_flow_list',{}]]},{id:'logic',title:'Check logic & assumptions',purpose:'Create a finite model, simulate reproducible paths, inspect counterexamples and export TLA+. Source observations and model coverage stay distinct.',names:['logic_model'],starters:[['Explore diff decisions','logic_model',{action:'run',template:'diff-lines',mode:'check',coverage:true}],['Simulate workflow continuation','logic_model',{action:'run',template:'workflow-continuation',mode:'simulate',seed:42,steps:30,traces:10,coverage:true}],['Check TLC availability','logic_model',{action:'diagnostics'}]]},{id:'views',title:'Name and connect pages',purpose:'Give a retained result or shared definition a readable /show name. Publish scoped events without executing an action.',names:['named_view','ui_event','ui_page'],starters:[['Browse named views','named_view',{action:'list'}],['Discover page examples','ui_page',{action:'templates'}]]}];
async function api(url,body,signal){const r=await fetch(url,{method:body===undefined?'GET':'POST',headers:{'content-type':'application/json','x-dt-story':story,...(principal?{'x-dt-principal':principal}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal});const value=await r.json();if(!r.ok)throw Error(value.error||'Request failed ('+r.status+')');return value;}
function status(text,error=false){$('studioStatus').textContent=text;$('studioStatus').style.color=error?'var(--bad)':'';}
function clearEvidence(){last=null;executedRequest=null;$('studioOutput').textContent='';$('studioRunRequest').textContent='';$('studioResult').hidden=true;$('studioResult').removeAttribute('src');$('studioNext').replaceChildren();$('studioEvidence').open=false;}
function navigation(){const scope=new URLSearchParams({story,...(principal?{principal}:{})});$('studioEditor').href='/editor?'+scope;$('studioPages').href='/pages?'+scope;}
function prepare(name,args={}){if(busy)return;clearEvidence();current=tools.find(t=>t.name===name);if(!current){status('This action is unavailable for your access or configuration.',true);return;}$('studioTool').value=name;$('studioDescription').textContent=current.description.split(/\.\s/)[0]+'.';$('studioFullDescription').textContent=current.description;form?.destroy();form=dtToolForm.mount($('studioFields'),current.inputSchema,args,values=>{clearEvidence();$('studioRequest').textContent=JSON.stringify({tool:name,arguments:values},null,2);},{tool:name,secondary:name==='logic_model'?['name','model','expected_revision','engine','seed','steps','traces','timeoutMs']:name==='continuation_create'?['contexts','projects','tickets','repositories','workspaces','chats','tasks','tags']:[]});$('studioSchema').textContent=JSON.stringify(current.inputSchema,null,2);$('studioRequest').textContent=JSON.stringify({tool:name,arguments:args},null,2);$('studioWorkbench').href='/admin#workbench?'+new URLSearchParams({tool:name,args:JSON.stringify(args)});status('Prepared '+name+'. Review the arguments, then Run action.');}
function intent(id){if(busy)return;const item=intents.find(i=>i.id===id)||intents[0];for(const b of $('studioIntents').children)b.setAttribute('aria-current',b.dataset.intent===item.id);$('studioIntentPick').value=item.id;$('studioTitle').textContent=item.title;$('studioPurpose').textContent=item.purpose;$('studioTool').replaceChildren(...tools.filter(t=>item.names.some(n=>n.endsWith('_')?t.name.startsWith(n):t.name===n)).map(t=>new Option(t.name,t.name)));$('studioStarters').replaceChildren();for(const [label,name,args]of item.starters){if(!tools.some(t=>t.name===name))continue;const b=document.createElement('button');b.textContent=label;b.onclick=()=>prepare(name,args);$('studioStarters').append(b);}if($('studioTool').options.length)prepare($('studioTool').value);else status('No actions in this area are enabled for your access.',true);history.replaceState(null,'','/studio?'+new URLSearchParams({intent:item.id,story,...(principal?{principal}:{}),...(q.get('embed')?{embed:'true'}:{})}));}
function next(result){$('studioNext').replaceChildren();const add=(label,name,args)=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>prepare(name,args);$('studioNext').append(b);};const flowStep=(label,action,args)=>add(label,result.continuationId?'continuation_flow':'automation_flow_'+action,result.continuationId?{id:result.continuationId,action,arguments:args}:args);if(current.name==='automation_flow_save'||current.name==='continuation_flow'&&result.flowAction==='save')flowStep('Start this reviewed revision','start',{id:result.id,expected_revision:result.revision,allow_model:false});const run=result.run||(result.protocol==='dt.automation-flow-run/v1'?result.id:null);if(run&&(current.name.startsWith('automation_flow_')||current.name==='continuation_flow')){flowStep('Observe saved checkpoint','status',{run,detail:true});if(result.canResume!==false)flowStep('Prepare resume','resume',{run,allow_model:false});if(result.canCancel!==false)flowStep('Cancel workflow','cancel',{run});}if(result.job&&current.name==='gradle_inventory')add('Observe the same index job','gradle_inventory',{job:result.job});if(result.revision&&current.name==='gradle_inventory')add('Read this immutable index','gradle_inventory',{action:'read',revision:result.revision});if(current.name==='continuation_find')for(const task of (result.continuations||[]).slice(0,20))add('Attach '+(task.taskId||task.title),'continuation_attach',{id:task.id});if(current.name==='continuation_create'||current.name==='continuation_attach'){const id=result.id||result.task?.id;if(id)add('Read task briefing','continuation_briefing',{id});}}
$('studioRun').onclick=async()=>{if(busy||!current)return;const issues=form.errors();if(issues.length){status(issues.join('; '),true);return;}busy=true;root.dataset.busy='true';$('studioRun').disabled=true;$('studioTool').disabled=true;controller=new AbortController();execution=null;$('studioCancel').hidden=false;status('Running '+current.name+'…');const args=form.value();clearEvidence();executedRequest=structuredClone({tool:current.name,arguments:args,story});$('studioRunRequest').textContent=JSON.stringify(executedRequest,null,2);try{const r=await api('/api/tool/'+current.name,args,controller.signal);last=r.result??r;execution=r.executionId;$('studioOutput').textContent=JSON.stringify(last,null,2);$('studioEvidence').open=true;const view=last.view;$('studioEvidence').open=!view;if(typeof view==='string'&&new URL(view,location.origin).origin===location.origin){(globalThis.DTToolSocket?.resultFrame || ((f,u)=>{f.src=u;}))($('studioResult'),new URL(view,location.origin).pathname);$('studioResult').hidden=false;}else{$('studioResult').hidden=true;$('studioResult').removeAttribute('src');}status([current.name,last.state||last.status||'completed',last.run?'run '+last.run:null,last.job?'job '+last.job:null].filter(Boolean).join(' · '));next(last);}catch(e){status(e.name==='AbortError'?'Request disconnected. Inspect the owned execution before retrying; completed effects may remain.':e.message,true);}finally{busy=false;root.dataset.busy='false';$('studioRun').disabled=false;$('studioTool').disabled=false;$('studioCancel').hidden=true;controller=null;}};
$('studioCancel').onclick=()=>controller?.abort();$('studioCopy').onclick=async()=>{if(!current)return;const args=form.value(),value=JSON.stringify({tool:current.name,arguments:args},null,2);try{await navigator.clipboard.writeText(value);status('Reproducible tool call copied.');}catch{$('studioRequest').textContent=value;$('studioEvidence').open=true;status('Select the reproducible call below to copy it.');}};$('studioTool').onchange=()=>prepare($('studioTool').value);$('studioStory').value=story;$('studioScope').onclick=()=>{if(busy){status('Wait for this request before changing scope.',true);return;}story=$('studioStory').value.trim()||'default';clearEvidence();navigation();intent(q.get('intent')||'continue');};for(const item of intents){$('studioIntentPick').append(new Option(item.title,item.id));const b=document.createElement('button');b.textContent=item.title;b.dataset.intent=item.id;b.onclick=()=>intent(item.id);$('studioIntents').append(b);}navigation();$('studioIntentPick').onchange=()=>intent($('studioIntentPick').value);window.addEventListener('message',event=>{if(event.source!==$('studioResult').contentWindow||event.data?.type!=='iframe:height'||!Number.isFinite(event.data.height))return;$('studioResult').style.height=Math.max(240,Math.min(1200,event.data.height+8))+'px';});window.studioCanLeave=()=>!busy;window.studioState=()=>({story,current:current?.name,busy,last,executedRequest});api('/api/tools').then(r=>{tools=Array.isArray(r)?r:r.tools||[];intent(q.get('intent')||'continue');}).catch(e=>status(e.message,true));})();
